class Solution {
    public int splitArray(int[] nums, int k) {
        long lo = 0, hi = 0;
        for (int num : nums) { lo = Math.max(lo, num); hi += num; }
        while (lo < hi) {
            long mid = lo + (hi - lo) / 2;
            if (canSplit(nums, k, mid)) hi = mid;
            else lo = mid + 1;
        }
        return (int) lo;
    }
    private boolean canSplit(int[] nums, int k, long maxSum) {
        int count = 1;
        long curSum = 0;
        for (int num : nums) {
            curSum += num;
            if (curSum > maxSum) { count++; curSum = num; }
        }
        return count <= k;
    }
}

class Solution {
    public int splitArray(int[] nums, int k) {
        int n = nums.length;
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + nums[i];
        long[][] dp = new long[k + 1][n + 1];
        for (long[] row : dp) java.util.Arrays.fill(row, Long.MAX_VALUE);
        dp[0][0] = 0;
        for (int i = 1; i <= k; i++) {
            for (int j = i; j <= n; j++) {
                for (int m = i - 1; m < j; m++) {
                    long lastSum = prefix[j] - prefix[m];
                    long val = Math.max(dp[i - 1][m], lastSum);
                    dp[i][j] = Math.min(dp[i][j], val);
                }
            }
        }
        return (int) dp[k][n];
    }
}
